extends Node

@warning_ignore("unused_signal")
signal dice_score_set(dice_range: Vector2, value: int)
signal gold_updated(value)
signal fame_updated(value)
signal hole_updated(value)

var course_data: CourseResource
var course_grid: CourseGrid
var dir_selector: DirectionSelector
var golfer_controller : GolferController
var skill_trhee: Node2D
var active_camera : Camera2D
var global_course : Node2D

var shots_chance = 4
var rerolls: int = 0

var gold : int = 0:
	set(value):
		var old_gold = gold
		gold = value
		if old_gold  != value:
			gold_updated.emit(gold)

var fame : int = 0:
	set(value):
		var old_fame = fame
		fame = value
		if old_fame != value:
			fame_updated.emit(fame)

var hole_count : int = 0:
	set(value):
		var old_hole = hole_count
		hole_count = value
		if old_hole  != value:
			hole_updated.emit(hole_count)

var user_count : int = 0
var spectator_count : int = 0
var tournament_running : bool  = false

var gold_time :float = 0.0


func can_buy(costs : Dictionary[Enums.Ressources,int],buy = false) :
	if costs[Enums.Ressources.GOLD] > gold:
		return false
	if costs[Enums.Ressources.FAME]  > fame:
		return false
	if costs[Enums.Ressources.HOLE] > hole_count:
		return false
	if buy :
		gold -= costs[Enums.Ressources.GOLD]
	return true

func player_do_hole(zone_type:String,first_time = false):
	var base_g_value = 1
	if first_time :
		base_g_value = 2
	var g_value = (base_g_value +  SkillsManager.player_gold_bonus) * SkillsManager.player_bonus_multiplier
	gold += g_value
	if SkillsManager.zone_gold_bonus[zone_type] > 0:
		gold += g_value * SkillsManager.zone_gold_bonus[zone_type]

	if first_time :
		var h_value = (1 +  SkillsManager.player_gold_bonus)  * SkillsManager.player_bonus_multiplier
		hole_count += h_value

	var f_value = (SkillsManager.player_reputation_bonus ) * SkillsManager.player_bonus_multiplier
	fame += f_value

	spectator_count += SkillsManager.spectators_per_golf * SkillsManager.player_bonus_multiplier

func user_do_hole(zone_type:String):
	hole_count += (1) 
	spectator_count += SkillsManager.spectators_per_hole
	var g_value = (1) 
	gold += g_value
	if SkillsManager.zone_gold_bonus[zone_type] > 0:
		gold += g_value * SkillsManager.zone_gold_bonus[zone_type]

func gain_gold_by_time():
	var gold_per_spectator = (1 + SkillsManager.gold_per_second_per_spectator )
	if tournament_running : 
		gold_per_spectator += gold_per_spectator * SkillsManager.tournament_gold_bonus
	gold += spectator_count * gold_per_spectator

func on_tournament_end():
	fame += SkillsManager.tournament_reputation_gain


func _process(delta: float) -> void:
	if spectator_count > 0 :
		gold_time += delta
		if gold_time >1.0:
			gain_gold_by_time()
			gold_time = 0.0


func _input(event: InputEvent) -> void:
	if  OS.has_feature("editor"):
		if event.is_action_pressed("cheat_fame"):
			fame += 10
		if event.is_action_pressed("cheat_gold"):
			gold +=10
		if event.is_action_pressed("cheat_hole"):
			hole_count += 10

func init_new_course():
	rerolls = SkillsManager.rerolls_per_hole +1
	shots_chance = SkillsManager.shot_count +4
