extends Node2D
class_name CourseGrid

signal grid_initialized(start_position: Vector2)

@export var grid_width: int = 30
@export var grid_height: int = 16
@export var zone_type: String = "green"  # Type de zone actuelle
@export var use_generated: bool = true  # Utiliser la génération ou le terrain de test

@onready var placeholder: ColorRect = $Placeholder
@onready var ball: Node2D = $"../Ball"
@onready var golfer: Golfer = $"../Golfer"
@onready var control_map: Control = $ControlMap

const TILE_PRESET = preload("res://scene/tile.tscn")
const TILE_SIZE := 32
const BONUS = preload("res://scene/grid_elements/bonus.tscn")

var grid: Array[Enums.TileType] = []
var corners: Array[Tile.TileCorner] = []
var course_data: CourseResource
var hole_pos : Vector2i

var locked: bool:
	set(value):
		locked = value
		if value:
			modulate.a = .5
		else:
			modulate.a = 1.

func _ready() -> void:
	GameManager.course_grid = self

func initialize_grid(generated_course: CourseResource,start_playing = false) -> CourseResource:
	placeholder.queue_free()

	if use_generated:
		# Déterminer quelle zone charger selon les skills débloqués
		var available_zone = _get_highest_unlocked_zone()
		if available_zone != "":
			zone_type = available_zone

		if generated_course == null:
			course_data = CourseGenerator.generate_course(zone_type)
		else:
			course_data = generated_course
		grid_width = course_data.grid_width
		grid_height = course_data.grid_height

		# Charger les tiles depuis les données générées
		grid = course_data.tiles.duplicate()
		corners = []
		for i in range(grid.size()):
			corners.append(Tile.TileCorner.NONE)

		# Appliquer les coins pour les rectangles d'obstacles
		#for obstacle in course_data.obstacles:
			#_apply_rectangle_corners(obstacle.rect)
		for tile_index in course_data.tiles.size():
			var tile_position := grid_to_coords(tile_index)
			var tile := course_data.tiles[tile_index]

			var cornered_tiles := [Enums.TileType.FAIRWAY, Enums.TileType.SAND, Enums.TileType.GREEN, Enums.TileType.TREE]
			if tile not in cornered_tiles:
				continue

			var left_position := tile_position + Vector2i.LEFT
			var left_tile : Enums.TileType
			if is_valid_position(left_position):
				left_tile = course_data.tiles[coords_to_grid(left_position)]

			var righ_position := tile_position + Vector2i.RIGHT
			var right_tile : Enums.TileType
			if is_valid_position(righ_position):
				right_tile = course_data.tiles[coords_to_grid(righ_position)]

			var top_position := tile_position + Vector2i.UP
			var top_tile : Enums.TileType
			if is_valid_position(top_position):
				top_tile = course_data.tiles[coords_to_grid(top_position)]

			var bottom_position := tile_position + Vector2i.DOWN
			var bottom_tile : Enums.TileType
			if is_valid_position(bottom_position):
				bottom_tile = course_data.tiles[coords_to_grid(bottom_position)]

			if left_tile == Enums.TileType.NORMAL and top_tile == Enums.TileType.NORMAL:
				corners[tile_index] = Tile.TileCorner.TOP_LEFT
			if right_tile == Enums.TileType.NORMAL and top_tile == Enums.TileType.NORMAL:
				corners[tile_index] = Tile.TileCorner.TOP_RIGHT
			if right_tile == Enums.TileType.NORMAL and bottom_tile == Enums.TileType.NORMAL:
				corners[tile_index] = Tile.TileCorner.BOTTOM_RIGHT
			if left_tile == Enums.TileType.NORMAL and bottom_tile == Enums.TileType.NORMAL:
				corners[tile_index] = Tile.TileCorner.BOTTOM_LEFT

		print("Terrain généré - Zone: ", zone_type, " Difficulté: ", course_data.difficulty_score)
	else:
		# Utiliser l'ancien système de terrain de test
		_initialize_test_grid()
	if start_playing :
		var ad = GridElement.new()
		ad.type = GridElement.ElementType.SHOT_BONUS
		ad.pos =  course_data.start_position + Vector2(randi_range(-4,-8),randi_range(-2,-5))
		course_data.additional_elements.append(ad)
	draw_grid()

	return course_data

func _get_highest_unlocked_zone() -> String:
	# Vérifier les zones débloquées dans l'ordre de difficulté
	var zones_order = ["hell", "celeste", "pink", "red", "yellow", "blue", "green"]

	for zone in zones_order:
		if zone in SkillsManager.unlocked_zones:
			return zone

	return "green"  # Par défaut

func _initialize_test_grid():
	# Ancien code du terrain de test
	grid = []
	for x in range(grid_width * grid_height):
		grid.append(Enums.TileType.NORMAL)
		corners.append(Tile.TileCorner.NONE)

	# Bunker
	set_rectangle_type(Rect2i(Vector2i(12, 2), Vector2i(2, 2)), Enums.TileType.SAND)
	set_rectangle_type(Rect2i(Vector2i(15, 8), Vector2i(2, 3)), Enums.TileType.SAND)

	# Green
	set_rectangle_type(Rect2i(Vector2i(3, 6), Vector2i(4, 4)), Enums.TileType.GREEN)

	# Hole
	set_tile_type(Vector2i(4, 8), Enums.TileType.HOLE)

	# Trees
	set_rectangle_type(Rect2i(Vector2i(5, 1), Vector2i(3, 2)), Enums.TileType.TREE)
	set_rectangle_type(Rect2i(Vector2i(8, 12), Vector2i(6, 3)), Enums.TileType.TREE)
	set_rectangle_type(Rect2i(Vector2i(19, 4), Vector2i(3, 4)), Enums.TileType.TREE)

	# Start
	set_rectangle_type(Rect2i(Vector2i(25, 3), Vector2i(5, 7)), Enums.TileType.FAIRWAY)
	set_tile_type(Vector2i(27, 6), Enums.TileType.START)

func _apply_rectangle_corners(rect: Rect2i):
	# Appliquer les coins pour un rectangle
	var tl = rect.position
	var tr = Vector2i(rect.position.x + rect.size.x - 1, rect.position.y)
	var bl = Vector2i(rect.position.x, rect.position.y + rect.size.y - 1)
	var br = rect.position + rect.size - Vector2i(1, 1)

	set_corner_type(tl, Tile.TileCorner.TOP_LEFT)
	set_corner_type(tr, Tile.TileCorner.TOP_RIGHT)
	set_corner_type(bl, Tile.TileCorner.BOTTOM_LEFT)
	set_corner_type(br, Tile.TileCorner.BOTTOM_RIGHT)

func coords_to_grid(grid_position: Vector2i) -> int:
	var grid_index := grid_position.y * grid_width + grid_position.x
	return grid_index

func grid_to_coords(grid_index: int) -> Vector2i:
	var grid_position_y := floori(float(grid_index) / float(grid_width))
	var grid_position_x := grid_index - grid_position_y * grid_width
	return Vector2i(grid_position_x, grid_position_y)

func set_rectangle_type(rect: Rect2i, type: Enums.TileType):
	for x in range(rect.position.x, rect.position.x + rect.size.x):
		for y in range(rect.position.y, rect.position.y + rect.size.y):
			set_tile_type(Vector2i(x, y), type)
			if y == rect.position.y && x == rect.position.x:
				set_corner_type(Vector2i(x, y), Tile.TileCorner.TOP_LEFT)
			if y == rect.position.y && x == rect.position.x + rect.size.x - 1:
				set_corner_type(Vector2i(x, y), Tile.TileCorner.TOP_RIGHT)
			if y == rect.position.y + rect.size.y - 1 && x == rect.position.x:
				set_corner_type(Vector2i(x, y), Tile.TileCorner.BOTTOM_LEFT)
			if y == rect.position.y + rect.size.y - 1 && x == rect.position.x + rect.size.x - 1:
				set_corner_type(Vector2i(x, y), Tile.TileCorner.BOTTOM_RIGHT)

func set_tile_type(tile_position: Vector2i, type: Enums.TileType):
	if (tile_position.x >= 0 and tile_position.x < grid_width and 
		tile_position.y >= 0 and tile_position.y < grid_height):
		grid[coords_to_grid(tile_position)] = type

func set_corner_type(tile_position: Vector2i, type: Tile.TileCorner):
	if (tile_position.x >= 0 and tile_position.x < grid_width and 
		tile_position.y >= 0 and tile_position.y < grid_height):
		corners[coords_to_grid(tile_position)] = type

func get_tile_type(tile_position: Vector2i) -> Enums.TileType:
	if is_valid_position(tile_position):
		return grid[coords_to_grid(tile_position)]

	# (4, 17) pose probleme

	#assert(false, str("The coords ", tile_position, " for grid are not valid"))
	return Enums.TileType.NORMAL

func get_corner_type(tile_position: Vector2i) -> Tile.TileCorner:
	if is_valid_position(tile_position):
		return corners[coords_to_grid(tile_position)]

	assert(false, str("The coords ", tile_position, " for corners are not valid"))
	return Tile.TileCorner.NONE

func is_valid_position(tile_position: Vector2i):
	var x = int(tile_position.x)
	var y = int(tile_position.y)

	if x < 0 or y < 0 or x >= grid_width or y >= grid_height:
		return false

	return true

func draw_grid():
	var start_position: Vector2i

	# Si on utilise un terrain généré, utiliser les positions stockées
	if use_generated:
		start_position = course_data.start_position

	for i in range(grid.size()):
		var tile_position = grid_to_coords(i)

		var tile: Tile = TILE_PRESET.instantiate()
		tile.position = Vector2(tile_position.x * TILE_SIZE + 1, tile_position.y * TILE_SIZE + 1)
		add_child(tile)
		tile.type = Enums.TileType.NORMAL
		tile.set_position_debug(tile_position)
		# Dirt only in last line of grass
		if i < grid.size() - grid_width:
			tile.hide_dirt()

		# Tiles spéciales
		if get_tile_type(tile_position) != Enums.TileType.NORMAL:
			var special_tile: Tile = TILE_PRESET.instantiate()
			special_tile.position = Vector2(tile_position.x * TILE_SIZE + 1, tile_position.y * TILE_SIZE + 1)
			add_child(special_tile)
			special_tile.type = get_tile_type(tile_position)
			special_tile.corner = get_corner_type(tile_position)
			special_tile.hide_debug()

		if get_tile_type(tile_position) == Enums.TileType.START:
			start_position = tile_position

	# Appliquer les bonus de zone si nécessaire
	if use_generated and zone_type != "green":
		_apply_zone_visual_effects()

	for ad : GridElement in course_data.additional_elements:
		var bonus = BONUS.instantiate()
		bonus.position =  Vector2(ad.pos.x * TILE_SIZE + 15, ad.pos.y * TILE_SIZE + 15)
		add_child(bonus)
		ad.object = bonus
	grid_initialized.emit(start_position)

func _apply_zone_visual_effects():
	# Effets visuels selon la zone
	match zone_type:
		"blue":
			modulate = Color(0.9, 0.95, 1.0)  # Teinte bleutée
		"yellow":
			modulate = Color(1.0, 0.98, 0.85)  # Teinte jaune
		"red":
			modulate = Color(1.0, 0.9, 0.9)  # Teinte rouge
		"pink":
			modulate = Color(1.0, 0.92, 0.95)  # Teinte rose
		"celeste":
			modulate = Color(0.85, 0.95, 1.0)  # Teinte céleste
		"hell":
			modulate = Color(1.0, 0.85, 0.85)  # Teinte infernale
			# Peut-être ajouter des particules de feu ?

func are_coords_in_course(coords: Vector2i) -> bool:
	if coords.x >= 0 and coords.x < grid_width and coords.y >= 0 and coords.y < grid_height:
		return true

	return false

# Fonction pour régénérer le terrain (utile pour tester)
func regenerate_course():
	# Nettoyer les tiles actuelles
	for child in get_children():
		if child != placeholder:
			child.queue_free()

	# Réinitialiser et régénérer
	initialize_grid(null)


