static func generate_course(zone_type: String, seed_value: int = -1) -> CourseResource:
	if seed_value == -1:
		seed_value = randi()

	seed(seed_value)

	var config = ZONE_CONFIGS.get(zone_type, ZONE_CONFIGS["green"])
	var grid_size = config["grid_size"]

	var course_data = CourseResource.new()
	course_data.zone_type = zone_type
	course_data.random_seed = seed_value
	course_data.grid_width = grid_size.x
	course_data.grid_height = grid_size.y
	course_data.difficulty_score = 0

	# Initialiser la grille
	for i in range(grid_size.x * grid_size.y):
		course_data.tiles.append(Enums.TileType.NORMAL)

	# Générer le parcours
	_place_start_and_hole(course_data)
	_place_fairway(course_data, config)
	_place_green(course_data, config)
	_place_obstacles(course_data, config)

	# Calculer le score de difficulté
	course_data.difficulty_score = _calculate_difficulty_score(course_data, config)

	return course_data

static func _place_start_and_hole(course_data: CourseResource) -> void:
	var width = course_data.grid_width
	var height = course_data.grid_height

	# Placer le départ dans le dernier quart droit
	var start_x = randi_range(width * 3 / 4, width - 1)
	var start_y = randi_range(2, height - 3)
	course_data.start_position = Vector2(start_x, start_y)
	_set_tile_type(course_data, course_data.start_position, Enums.TileType.START)

	# Placer le trou dans le premier quart gauche
	var hole_x = randi_range(2, width / 4)
	var hole_y = randi_range(2, height - 3)
	course_data.hole_position = Vector2(hole_x, hole_y)

	# Zone de départ
	var start_rect = Rect2i(
		course_data.start_position - Vector2(1, 1),
		Vector2(3, 3)
	)
	course_data.fairways.append(CourseResource.Obstacle.new("fairway", start_rect))
	_set_rectangle_type(course_data, start_rect, Enums.TileType.FAIRWAY)

static func _place_fairway(course_data: CourseResource, config: Dictionary) -> void:
	# Créer un chemin sinueux entre start et hole
	var path_points = _generate_curved_path(course_data.start_position, course_data.hole_position, 3)

	for i in randi_range(config.fairway_count_range.x, config.fairway_count_range.y):
		var random_path_point = randi() % (path_points.size() - 2) + 1
		var point = path_points[random_path_point]
		var fairway_width = randi_range(config.fairway_size_range.x, config.fairway_size_range.y)
		var fairway_height = randi_range(config.fairway_size_range.x, config.fairway_size_range.y)
		var rect := Rect2i(
			point - Vector2(fairway_width / 2, fairway_height / 2),
			Vector2(fairway_width, fairway_height)
		)
		course_data.fairways.append(CourseResource.Obstacle.new("fairway", rect))
		_set_rectangle_type(course_data, rect, Enums.TileType.FAIRWAY)

static func _place_continous_fairway(course_data: CourseResource, config: Dictionary) -> void:
	var start = course_data.start_position
	var hole = course_data.hole_position
	var fairway_width = randi_range(config.fairway_size_range.x, config.fairway_size_range.y)

	# Créer un chemin sinueux entre start et hole
	var path_points = _generate_curved_path(start, hole, 3)

	# Élargir le chemin pour créer le fairway
	for point in path_points:
		var rect = Rect2i(
			point - Vector2(fairway_width / 2, fairway_width / 2),
			Vector2(fairway_width, fairway_width)
		)
		_set_rectangle_type(course_data, rect, Enums.TileType.FAIRWAY)

	# Zone de départ
	var start_rect = Rect2i(
		start - Vector2(2, 2),
		Vector2(4, 4)
	)
	_set_rectangle_type(course_data, start_rect, Enums.TileType.FAIRWAY)

static func _place_green(course_data: CourseResource, config: Dictionary) -> void:
	var green_size = randi_range(config.green_size_range.x, config.green_size_range.y)

	# Créer le green autour du trou
	var green_rect = Rect2i(
		course_data.hole_position - Vector2(green_size / 2, green_size / 2),
		Vector2(green_size, green_size)
	)
	_set_rectangle_type(course_data, green_rect, Enums.TileType.GREEN)
	_set_tile_type(course_data, course_data.hole_position, Enums.TileType.HOLE)

static func _place_obstacles(course_data: CourseResource, config: Dictionary) -> void:
	var start = course_data.start_position
	var hole = course_data.hole_position

	# Placer les bunkers de sable
	var sand_count = randi_range(config.sand_count_range.x, config.sand_count_range.y)
	for i in range(sand_count):
		var pos = _get_strategic_obstacle_position(course_data, config, start, hole, Enums.TileType.SAND)
		if pos != Vector2(-1, -1):
			var size = Vector2(randi_range(2, 4), randi_range(2, 3))
			var rect = Rect2i(pos, size)
			_set_rectangle_type(course_data, rect, Enums.TileType.SAND)
			course_data.obstacles.append(CourseResource.Obstacle.new("sand", rect))

	# Placer les arbres
	var tree_count = randi_range(config.tree_count_range.x, config.tree_count_range.y)
	for i in range(tree_count):
		var pos = _get_strategic_obstacle_position(course_data, config, start, hole, Enums.TileType.TREE)
		if pos != Vector2(-1, -1):
			var size = Vector2(randi_range(2, 4), randi_range(2, 4))
			var rect = Rect2i(pos, size)
			_set_rectangle_type(course_data, rect, Enums.TileType.TREE)
			course_data.obstacles.append(CourseResource.Obstacle.new("tree", rect))

static func _get_strategic_obstacle_position(course_data: CourseResource, config: Dictionary, start: Vector2, hole: Vector2, type: Enums.TileType) -> Vector2:
	var width = course_data.grid_width
	var height = course_data.grid_height
	var max_attempts = 50

	for attempt in range(max_attempts):
		var pos: Vector2

		# Décider si l'obstacle est aligné avec la trajectoire
		if randf() < config.obstacle_alignment_chance:
			# Placer sur la ligne entre start et hole
			var t = randf_range(0.2, 0.8)  # Éviter trop proche du départ ou du trou
			var line_pos = start.lerp(hole, t)
			var offset = Vector2(randi_range(-3, 3), randi_range(-3, 3))
			pos = line_pos + offset
		else:
			# Placement aléatoire
			pos = Vector2(randi_range(2, width - 4), randi_range(2, height - 4))

		# Vérifier que la position est valide
		if _is_valid_obstacle_position(course_data, pos, type):
			return pos

	return Vector2(-1, -1)  # Échec

static func _is_valid_obstacle_position(course_data: CourseResource, pos: Vector2, type: Enums.TileType) -> bool:
	# Vérifier les limites
	if pos.x < 1 or pos.y < 1 or pos.x >= course_data.grid_width - 3 or pos.y >= course_data.grid_height - 3:
		return false

	# Ne pas placer sur le départ, le trou, le green ou le fairway
	var protected_tiles = [Enums.TileType.START, Enums.TileType.HOLE, Enums.TileType.GREEN, Enums.TileType.FAIRWAY]
	for x in range(pos.x - 1, pos.x + 4):
		for y in range(pos.y - 1, pos.y + 4):
			var tile_type = _get_tile_type(course_data, Vector2(x, y))
			if tile_type in protected_tiles:
				return false

	return true

static func _generate_curved_path(start: Vector2, end: Vector2, curve_points: int):
	var path = []
	var control_points = [start]

	# Générer des points de contrôle pour la courbe
	for i in range(curve_points):
		var t = (i + 1.0) / (curve_points + 1.0)
		var base_point = start.lerp(end, t)
		var perpendicular = (end - start).orthogonal().normalized()
		var offset = perpendicular * randf_range(-5, 5)
		control_points.append(base_point + Vector2(offset))

	control_points.append(end)

	# Interpoler entre les points de contrôle
	for i in range(control_points.size() - 1):
		var segment_start = control_points[i]
		var segment_end = control_points[i + 1]
		var steps = int(segment_start.distance_to(segment_end) / 2)

		for step in range(steps):
			var t = float(step) / float(steps)
			var point = segment_start.lerp(segment_end, t)
			path.append(point)

	path.append(end)
	return path

static func _calculate_difficulty_score(course_data: CourseResource, config: Dictionary) -> float:
	var score = config.difficulty * 100.0

	# Distance entre start et hole
	var distance = course_data.start_position.distance_to(course_data.hole_position)
	score += distance * 2

	# Nombre d'obstacles
	score += course_data.obstacles.size() * 10

	# Obstacles sur la trajectoire directe
	var aligned_obstacles = 0
	for obstacle in course_data.obstacles:
		var rect = obstacle.rect
		if _is_obstacle_on_line(rect, course_data.start_position, course_data.hole_position):
			aligned_obstacles += 1

	score += aligned_obstacles * 20

	# Taille du green (plus petit = plus difficile)
	var green_tiles = 0
	for tile in course_data.tiles:
		if tile == Enums.TileType.GREEN:
			green_tiles += 1

	score += (25 - green_tiles) * 5  # Inverser le score

	return score

static func _is_obstacle_on_line(rect: Rect2i, start: Vector2, end: Vector2) -> bool:
	# Vérifier si le rectangle intersecte la ligne entre start et end
	var line_dir = (end - start).normalized()
	var line_length = start.distance_to(end)

	for t in range(int(line_length)):
		var point = start + line_dir * t
		if rect.has_point(point):
			return true

	return false

# Fonctions utilitaires pour manipuler la grille
static func _coords_to_grid(course_data: CourseResource, grid_position: Vector2) -> int:
	return grid_position.y * course_data.grid_width + grid_position.x

static func _set_tile_type(course_data: CourseResource, tile_position: Vector2, type: Enums.TileType) -> void:
	if tile_position.x >= 0 and tile_position.x < course_data.grid_width and \
	   tile_position.y >= 0 and tile_position.y < course_data.grid_height:
		var index = _coords_to_grid(course_data, tile_position)
		if index < course_data.tiles.size():
			course_data.tiles[index] = type

static func _get_tile_type(course_data: CourseResource, tile_position: Vector2) -> Enums.TileType:
	if tile_position.x >= 0 and tile_position.x < course_data.grid_width and \
	   tile_position.y >= 0 and tile_position.y < course_data.grid_height:
		var index = _coords_to_grid(course_data, tile_position)
		if index < course_data.tiles.size():
			return course_data.tiles[index]
	return Enums.TileType.NORMAL

static func _set_rectangle_type(course_data: CourseResource, rect: Rect2i, type: Enums.TileType) -> void:
	for x in range(rect.position.x, min(rect.position.x + rect.size.x, course_data.grid_width)):
		for y in range(rect.position.y, min(rect.position.y + rect.size.y, course_data.grid_height)):
			_set_tile_type(course_data, Vector2(x, y), type)
