			modulate = Color(1.0, 0.92, 0.95)  # Teinte rose
		"celeste":
			modulate = Color(0.85, 0.95, 1.0)  # Teinte céleste
		"hell":
			modulate = Color(1.0, 0.85, 0.85)  # Teinte infernale
			# Peut-être ajouter des particules de feu ?

func are_coords_in_course(coords: Vector2i) -> bool:
	if coords.x >= 0 and coords.x < grid_width and coords.y >= 0 and coords.y < grid_height:
		return true

	return false

