var difficulty: int:
	set(value):
		difficulty = value
		difficulty_score.text = str(value)
var trajectory: Array[Vector2i]
var hovered_tile_position: Vector2i

static var ALLOWED_TRAJECTORIES: Array[Vector2i] = [
	Vector2i.RIGHT,
	Vector2i(1, -1),
	Vector2i(1, 1),
	Vector2i.LEFT,
	Vector2i(-1, -1),
	Vector2i(-1, 1),
	Vector2i.UP,
	Vector2i.DOWN
]

var TILE_TYPE_DIFFICULTY: Dictionary[Enums.TileType, float] = {
	Enums.TileType.NORMAL: 0.4,
	Enums.TileType.FAIRWAY: 0.3,
	Enums.TileType.TREE: 1.0,
	Enums.TileType.SAND: 0.8,
	Enums.TileType.GREEN: 0.4,
	Enums.TileType.HOLE: 0.4,
	Enums.TileType.START: 0.4,
}

static func find_closest_direction(from: Vector2i, to: Vector2i) -> Vector2i:
	var distance := int(from.distance_to(to))

	var smaller_distance: int = 1 << 16 # UINT16_MAX
	var smaller_trajectory_index: int
	for trajectory_index in ALLOWED_TRAJECTORIES.size():
		var allowed_trajectory := ALLOWED_TRAJECTORIES[trajectory_index]
		var estimated_finish := from + allowed_trajectory * distance
		var estimated_distance := int(estimated_finish.distance_to(to))
		if estimated_distance < smaller_distance:
			smaller_distance = int(estimated_finish.distance_to(to))
			smaller_trajectory_index = trajectory_index

	return ALLOWED_TRAJECTORIES[smaller_trajectory_index]

func _unhandled_input(event: InputEvent) -> void:
	if event is InputEventMouseMotion:
		preview_trajectory()
	if event is InputEventMouseButton:
		var input_event := event as InputEventMouseButton
		if input_event.pressed and input_event.button_index == MOUSE_BUTTON_LEFT:
			choose_trajectory()

func choose_trajectory() -> void:
	trajectory_locked = true
	save_trajectory()
	trajectory_chose.emit(trajectory, difficulty)

func preview_trajectory() -> void:
	if trajectory_locked: return

	var mouse_position := get_global_mouse_position()
	var grid_position := Vector2i(mouse_position) / GameManager.course_grid.TILE_SIZE

	if grid_position == hovered_tile_position:
		return

	hovered_tile_position = grid_position

	if not GameManager.course_grid.are_coords_in_course(grid_position):
		return

	var distance := int(golfer_controller.ball_pos.distance_to(grid_position))

	var smaller_trajectory := find_closest_direction(golfer_controller.ball_pos, grid_position)

	if smaller_trajectory != Vector2i.LEFT and smaller_trajectory != Vector2i.RIGHT and smaller_trajectory != Vector2i.UP and smaller_trajectory != Vector2i.DOWN:
		distance = ceili(float(distance) * .75)

	var smaller_trajectory_index := ALLOWED_TRAJECTORIES.find(smaller_trajectory)

	display_trajectory(golfer_controller.ball_pos, smaller_trajectory_index, distance, true)

func display_trajectory(ball_position: Vector2i, direction: int, power: int, skip_power_bonus := false):	
	clear_trajectory_display()

	trajectory = calculate_trajectory(ball_position, direction, power, skip_power_bonus)

	difficulty = calculate_trajectory_difficulty(ball_position, trajectory)
	difficulty_score.position = (ball_position + Vector2i.UP) * GameManager.course_grid.TILE_SIZE

	trajectory_change.emit(difficulty)

	if trajectory.size() == 0:
		return

	var is_possible = project_trajectory(ball_position)

	display_trajectory_visual(is_possible)

func calculate_trajectory(ball_position: Vector2i, direction: int, power: int, skip_power_bonus := false) -> Array[Vector2i]:
	var max_dice_value := Dices.max_dice().range.y

	var new_trajectory: Array[Vector2i] = []
	var start_pos := ball_position
	var direction_vector := Vector2i.ZERO
	var start_tile_type := GameManager.course_grid.get_tile_type(ball_position)
	if start_tile_type == Enums.TileType.START or start_tile_type == Enums.TileType.FAIRWAY and not skip_power_bonus:
		power += 1
	if start_tile_type == Enums.TileType.SAND and not skip_power_bonus:
		power -= 1
		if power <= 0 :
			power = 1

	match direction:
		Enums.dir.RIGHT:
			direction_vector = Vector2i(1, 0)
		Enums.dir.RIGHTTOP:
			direction_vector = Vector2i(1, -1)
		Enums.dir.RIGHTBOT:
			direction_vector = Vector2i(1, 1)
		Enums.dir.LEFT:
			direction_vector = Vector2i(-1, 0)
		Enums.dir.LEFTTOP:
			direction_vector = Vector2i(-1, -1)
		Enums.dir.LEFTBOT:
			direction_vector = Vector2i(-1, 1)
		Enums.dir.TOP:
			direction_vector = Vector2i(0, -1)
		Enums.dir.BOT:
			direction_vector = Vector2i(0, 1)

	for i in range(1, power + 1):
		var pos := start_pos + direction_vector * i

		if GameManager.course_grid.are_coords_in_course(pos):
			# Check if the trajectory is not above the maximum dice
			var trajectory_copy = new_trajectory.duplicate()
			trajectory_copy.append(pos)
			var current_difficulty := calculate_trajectory_difficulty(start_pos, trajectory_copy)
			if current_difficulty > max_dice_value:
				break
			new_trajectory.append(pos)
		else:
			break

	return new_trajectory

func calculate_trajectory_difficulty(ball_position: Vector2i, new_trajectory: Array[Vector2i]) -> int:
	var zone_type = GameManager.course_data.zone_type
	var zone_dificulty_modifier = 1.0
	var new_difficulty := 0.0

	for i in range(new_trajectory.size()):
		var pos := new_trajectory[i]
		var tile_type := GameManager.course_grid.get_tile_type(pos)
		new_difficulty += TILE_TYPE_DIFFICULTY[tile_type]

	var start_tile_type := GameManager.course_grid.get_tile_type(ball_position)
	new_difficulty *= zone_dificulty_modifier
	new_difficulty = roundf(new_difficulty)
	if start_tile_type == Enums.TileType.FAIRWAY:
		new_difficulty -= 1
	new_difficulty -= SkillsManager.dc_reduction_global
	if new_difficulty < 1.0 :
		new_difficulty = 1.0

	return int(new_difficulty)

func project_trajectory(ball_position: Vector2i) -> bool:
	if trajectory.size() == 0:
		return false

	var start_tile_type := GameManager.course_grid.get_tile_type(ball_position)

	var final_pos := trajectory[trajectory.size() - 1]
	var final_tile_type := GameManager.course_grid.get_tile_type(final_pos)

	# Si la case finale est un arbre, la trajectoire est impossible
	if final_tile_type == Enums.TileType.TREE:
		return false

	# Vérifier s'il y a des arbres sur le chemin
	var has_trees_on_path = false
	for i in range(trajectory.size() - 1):  # Exclure la case finale
		var pos := trajectory[i]
		var tile_type = GameManager.course_grid.get_tile_type(pos)
		if tile_type == Enums.TileType.TREE:
			has_trees_on_path = true
			break

	# Si il y a des arbres sur le chemin, la trajectoire n'est possible que si le tir se fait depuis fairway ou start
	if has_trees_on_path:
		if start_tile_type == Enums.TileType.FAIRWAY or start_tile_type == Enums.TileType.START:
			projected_ball_position = final_pos
			return true
		else:
			return false

	projected_ball_position = final_pos
	return true

func display_trajectory_visual(is_possible: bool):
	var color = Color.RED if not is_possible else Color.YELLOW

	for pos in trajectory:
		var indicator = ColorRect.new()
		indicator.mouse_filter = Control.MOUSE_FILTER_IGNORE
		indicator.color = color
		indicator.color.a = 1.0  # Transparence
		indicator.size = Vector2(GameManager.course_grid.TILE_SIZE/4, GameManager.course_grid.TILE_SIZE/4)
		indicator.position = Vector2(
			pos.x * GameManager.course_grid.TILE_SIZE + GameManager.course_grid.TILE_SIZE/2 - GameManager.course_grid.TILE_SIZE/8, 
			pos.y * GameManager.course_grid.TILE_SIZE + GameManager.course_grid.TILE_SIZE/2 - GameManager.course_grid.TILE_SIZE/8
		)
		indicator.name = "trajectory_indicator"
		indicators.add_child(indicator)

func clear_trajectory_display():
	for child in indicators.get_children():
		child.queue_free()

func save_trajectory():
	for child in indicators.get_children():
		child.color.a = 0.5
		child.reparent(previous_indicators)
