func _ready() -> void:
	GameManager.golfer_controller = self

func _quadratic_bezier(p0: Vector2, p1: Vector2, p2: Vector2, t: float):
	var q0 = p0.lerp(p1, t)
	var q1 = p1.lerp(p2, t)
	var r = q0.lerp(q1, t)
	return r

func move_ball(ball_trajectory: Array[Vector2i], difficulty: int, _dice_range: Vector2, dice_score: int):
	var new_position := ball_trajectory[ball_trajectory.size() - 1]
	var course_data := GameManager.course_data
	var TILE_SIZE = GameManager.course_grid.TILE_SIZE
	#new_position = SkillsManager.apply_favorable_wind(new_position)

	if dice_score < difficulty:
		var fail_diff := difficulty - dice_score
		var fail_ratio := 1 - float(fail_diff) / float(difficulty)
		var fail_index := floori(ball_trajectory.size() * fail_ratio) - 1

		new_position = ball_trajectory[fail_index]
		var direction := ball_trajectory[ball_trajectory.size() - 1] - ball_trajectory[0]
		var direction_norm := direction / direction.abs().clampi(1, 10_000_000)

		var trajectories := Trajectory.ALLOWED_TRAJECTORIES.duplicate()
		trajectories.sort_custom(func(traj_a, traj_b): 
			return traj_a.distance_to(direction_norm) < traj_b.distance_to(direction_norm)
		)

		var variance_directions: Array[Vector2i] = [trajectories[3], trajectories[4]]
		var variance_direction : Vector2i = variance_directions.pick_random()
		var variance_power := fail_diff
		var pos_befor_variance = new_position
		var variance := variance_direction * variance_power
		print("Dice roll failed, shot variance: ", variance_direction, ", power: ", variance_power, " max (", fail_diff, ")", " total: ", variance)
		new_position += variance
		var out_limits = is_out_of_limite(new_position)
		if out_limits.out :
			for i in range(variance_power):
				pos_befor_variance +=variance_direction
				if is_out_of_limite(pos_befor_variance).out:
					new_position = pos_befor_variance-variance_direction
					break

	if new_position != null :
		ball_pos = new_position

		golfer.shoot()

		var tween = create_tween()
		var distance = previous_ball_pos.distance_to(ball_pos)
		var mid_pos = (Vector2(previous_ball_pos) - Vector2(ball_pos)) / 2. + Vector2(ball_pos) + (Vector2.UP * distance)

		tween.tween_method(func(value: float):
			var next_position = _quadratic_bezier(Vector2(previous_ball_pos) * TILE_SIZE, mid_pos * TILE_SIZE, Vector2(ball_pos) * TILE_SIZE, value)
			ball.position = next_position
		,0., 1., distance * .3).set_ease(Tween.EASE_IN).set_delay(0.8)
		tween.tween_callback(func():
			previous_ball_pos = Vector2i(ball_pos)
			ball_moved.emit(new_position, GameManager.course_grid.get_tile_type(ball_pos))
			golfer.walk_to(Vector2(ball_pos) * TILE_SIZE, true)
		)

func place_golfer(start_position: Vector2i):
	ball.position = start_position * GameManager.course_grid.TILE_SIZE
	golfer.position = start_position * GameManager.course_grid.TILE_SIZE

func is_out_of_limite(pos):
	var course_data := GameManager.course_data
	var out_top = false
	var out_left = false
	var out_right = false
	var out_bot = false
	var out = false
	if pos.x < 1 :
		out_right = true
		out = true
	if pos.x > course_data.grid_width-1 :
		out_left = true
		out = true
	if pos.y < 1 :
		out_bot = true
		out = true
	if pos.y > course_data.grid_height-1 :
		out_top = true
		out = true

	return {"out":out, "out_top":out_top, "out_bot":out_bot, "out_right":out_right, "out_left":out_left}
