extends Node2D

@onready var course_grid: CourseGrid = $CourseGrid
@onready var control_map: Control = $ControlMap

var is_moving = false
var block_placing := false
var is_new = false
# Called when the node enters the scene tree for the first time.
func _ready() -> void:
	if is_new :
		course_grid.initialize_grid(null)


# Called every frame. 'delta' is the elapsed time since the previous frame.
func _process(delta: float) -> void:
	pass

func selected():
	is_moving = true
	control_map.linkde_course = course_grid

func remove():
	CourseLedgerManager.courses.erase(course_grid.course_data)
	queue_free()

func _input(event: InputEvent) -> void:
	if !is_moving : 
		return
	if event is InputEventMouseMotion:
		_move_course()
		return
	if event is InputEventMouseButton:
		var button_input := event as InputEventMouseButton
		if not button_input.pressed and event.button_index == MOUSE_BUTTON_LEFT && not block_placing:
			_place_course()
		if not button_input.pressed and event.button_index == MOUSE_BUTTON_LEFT && block_placing:
			block_placing = false


func _move_course() -> void:
	if get_child_count() == 0:
		return

	var viewport := get_viewport()
	var camera := get_viewport().get_camera_2d()

	var grid: CourseGrid = get_child(0)
	var grid_offset := Vector2.ZERO

	if grid != null:
		grid_offset.x = grid.grid_width / 2. * GameManager.course_grid.TILE_SIZE
		grid_offset.y = grid.grid_height / 2. * GameManager.course_grid.TILE_SIZE

	position = (viewport.get_mouse_position() / camera.zoom + camera.position - (viewport.get_visible_rect().size / 2) - (grid_offset / camera.zoom)).snapped(Vector2.ONE * GameManager.course_grid.TILE_SIZE)


func _place_course() -> void:
	if get_child_count() == 0:
		return

	var grid: CourseGrid = get_child(0)

	if grid == null:
		return

	var grid_coords := position / GameManager.course_grid.TILE_SIZE
	var grid_rect := Rect2i(grid_coords, Vector2i(grid.grid_width, grid.grid_height))

	for course in CourseLedgerManager.courses:
		var coords := course.position / GameManager.course_grid.TILE_SIZE
		var course_rect := Rect2i(coords, Vector2i(course.grid_width, course.grid_height))
		if course_rect.intersects(grid_rect):
			return

	CourseLedgerManager.courses.append(course_grid.course_data)
	grid.locked = true
	is_moving = false
