}
const ROOT = 'C:/travaille/godot/papergoldrip'
const G = 'C:/travaille/godot/Godot_v4.5.1-stable_win64_console.exe'
const ctx = `Project: Godot 4.5 game "Dices Golf" at ${ROOT}. The pure-logic core is in script/core/*.gd with tests in tests/. Normative docs: doc/RULES_SPEC.md (numbered rules; ambiguities A1–A29 resolved by their 'Proposition'), doc/ARCHITECTURE.md, doc/Dices_Golf_GDD_v0.2.md, doc/INTEGRATION.md, data in res/data/. Other agents are concurrently building UI scenes in scene/ and script/autoloads/ — do NOT modify any project file except temporary tests you are explicitly allowed to create.`
const FIND_SCHEMA = { type: 'object', properties: { findings: { type: 'array', items: { type: 'object', properties: {
  id: { type: 'string' }, file: { type: 'string' }, line: { type: 'integer' }, rule: { type: 'string', description: 'rule id e.g. R-FAIL-03 or GDD section' },
