  required: ['id', 'file', 'summary', 'scenario', 'severity', 'rule'] } } }, required: ['findings'] }
const VERDICT = { type: 'object', properties: { confirmed: { type: 'boolean' }, evidence: { type: 'string' }, fix_hint: { type: 'string' } }, required: ['confirmed', 'evidence'] }
const DIMS = [
  { key: 'shot', focus: 'ShotRules + Attempt: legality, reach (A1), DC integer math (R-DC), failure table and deviation/fallback (R-FAIL), state machine transitions (R-SHOT), strokes/shots accounting, victory before defeat, abandon.' },
  { key: 'powers', focus: 'Attempt powers: rerolls, guards, criticals and refunds (each once), Focus, calibration/stability/anchor, legacies D6/D10/D20/D30 with own counters, wind draw timing and DC, push cap 2 and hole stop, bonus tiles (sites, thresholds vs bonus_extra_chance, slots, value, cap 4/attempt, collect on final position only), to_dict/from_dict exactness incl. RNG.' },
  { key: 'progression', focus: 'Progression + StatBlock + GameData: purchase transaction (all checks before pay, refusal no change, double buy), tier/level gating, gate_all, license grants first course once, campaign sequence offers and prices, additional price formula, validation only by manual win, first-clear bonus once per content, reward formula Z*M*F rounding, milestones require exact content ids, archive/restore/place, counters, to_dict/from_dict, stat rebuild set/add/caps.' },
  { key: 'economy', focus: 'Economy + SaveSystem: visitor cycles only on producing courses, rate shortens cycle not reward, fractions persist, public share capped 0.40 on visitor income, tournaments (eligible minute, chance, 180s event, multiplier, frozen prize paid once, 300s rest, no overlap), FPS independence, sub-cent handling, save atomicity/backup/version migration.' },
  { key: 'generator', focus: 'CourseGenerator + CourseSolver: determinism, constraints (tee/hole sides, reachable, not hole-in-one), bonus sites validity/stability, solver DP correctness vs ShotRules (does it mirror legality and failure outcomes exactly), policy legality (never attempts illegal actions), performance pitfalls, any hash()-based nondeterminism risk.' },
]
phase('Find')
const results = await pipeline(DIMS,
  d => agent(`${ctx}
You are an adversarial code reviewer. Focus area: ${d.focus}
Read the relevant core files fully and the matching RULES_SPEC sections, and compare line by line. Look for real correctness bugs: wrong rule implementation, off-by-one, wrong order of operations, missing cap, double payment, state leaks, serialization loss, type bugs (float/int from JSON), crashes on edge cases. Also check the existing tests for false confidence (tests that assert the wrong expectation). Do not report style. Each finding must have a concrete reproducing scenario. Max 12 findings, most severe first. Prefix ids with '${d.key}-'.`, { label: `find:${d.key}`, phase: 'Find', schema: FIND_SCHEMA }),
  (r, d) => parallel((r?.findings || []).map(f => () =>
    agent(`${ctx}
Adversarially VERIFY this claimed bug. Default to confirmed=false unless you reproduce it.
Finding ${f.id} [${f.severity}] in ${f.file}:${f.line ?? '?'} (rule ${f.rule}): ${f.summary}
Scenario: ${f.scenario}
Method: read the code; then write a temporary reproduction test file ${ROOT}/tests/test_zzv_${f.id.replace(/[^a-zA-Z0-9]/g, '_')}.gd (extends RefCounted, func test_repro(t) -> void using t.ok/t.eq) asserting the CORRECT behaviour per the spec, run it with: timeout 200 "${G}" --headless --path ${ROOT} -s tests/run_tests.gd -- zzv_${f.id.replace(/[^a-zA-Z0-9]/g, '_')}  ; then DELETE that test file (and its .uid if created). Also double-check the spec really says what the finding claims (the finding may misread the spec). confirmed=true only if the test fails because of the code and the spec clearly supports the finding. Put the test code and output in evidence, and a precise fix hint.`, { label: `verify:${f.id}`, phase: 'Verify', schema: VERDICT })
      .then(v => ({ ...f, verdict: v })))))
const all = results.flat().filter(Boolean)
return { confirmed: all.filter(f => f.verdict?.confirmed), rejected: all.filter(f => !f.verdict?.confirmed).map(f => ({ id: f.id, summary: f.summary, why: f.verdict?.evidence?.slice(0, 300) })) }

