export const meta = {
  name: 'dices-golf-branch-review',
  description: 'Adversarial review of feat/v02-core across 5 dimensions, each finding verified by an independent skeptic',
  phases: [
    { title: 'Review', detail: '5 dimension reviewers' },
    { title: 'Verify', detail: 'one skeptic per dimension tries to refute each finding' },
  ],
}

const CTX = `Dépôt Godot 4.5.1 C:/travaille/godot/papergoldrip, branche feat/v02-core (diff complet : git diff master...HEAD ; le prototype d'origine est sur master). Jeu "Dices Golf". Références : doc/claude.md (règles et invariants), doc/Dices_Golf_GDD_v0.2.md, doc/INTEGRATION.md, doc/RULES_SPEC.md (règles numérotées et ambiguïtés tranchées), doc/ARCHITECTURE.md, res/data/*. Godot : C:/travaille/godot/Godot_v4.5.1-stable_win64_console.exe ; tests "<godot> --headless --path . -s tests/run_tests.gd -- <filtre>". Tu peux écrire des scripts de reproduction headless dans C:/Users/akitl/AppData/Local/Temp/claude/C--travaille-godot-papergoldrip/84640d2f-4728-4b16-904d-02b49dbb5ac8/scratchpad/review2/ (extends SceneTree, lancés avec -s) mais NE MODIFIE AUCUN fichier du dépôt et ne committe rien.
Cherche de VRAIS défauts (comportement faux, invariant violé, crash, corruption de sauvegarde, incohérence règle/code/UI, effet de compétence non branché, test qui ne teste pas ce qu'il prétend). Pas de remarques de style. Chaque constat : fichier, ligne, scénario concret d'échec (entrées/état → résultat faux), sévérité, et idéalement une reproduction exécutée. Rédige en français.`

const FINDINGS = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          file: { type: 'string' },
          line: { type: 'integer' },
          severity: { type: 'string', enum: ['critical', 'major', 'minor'] },
          summary: { type: 'string' },
          failure_scenario: { type: 'string' },
          evidence: { type: 'string' },
        },
        required: ['id', 'file', 'line', 'severity', 'summary', 'failure_scenario', 'evidence'],
      },
    },
  },
  required: ['findings'],
}

const VERDICTS = {
  type: 'object',
  properties: {
    verdicts: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          verdict: { type: 'string', enum: ['CONFIRMED', 'PLAUSIBLE', 'REFUTED'] },
          reason: { type: 'string' },
          suggested_fix: { type: 'string' },
        },
        required: ['id', 'verdict', 'reason', 'suggested_fix'],
      },
    },
  },
  required: ['verdicts'],
}

const DIMS = [
