}
const VERDICT = { type: 'object', properties: { real: { type: 'boolean' }, reason: { type: 'string' } }, required: ['real', 'reason'] }
const REVIEWS = [
  { key: 'generator', focus: 'générateur v4 : v3 strictement inchangé, versions d\'instance (sauvegardes v3 conservent leurs tracés, endless en cours), archétypes réellement à branches (regarde des cartes ASCII), invariants, déterminisme, performance de génération.' },
