export const meta = {
  name: 'dices-golf-lot-D-videos',
  description: 'Lot D : vidéos Steam (trailer 60-90 s + gameplay 2-3 min, 1080p60 H.264) capturées avec Movie Maker de Godot 4.7.2 puis montées avec ffmpeg, revues et corrigées',
